import{_ as r,a as e,c as t,ac as s}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"小学二年级数学：独立习题集 · 倍的认识与倍数应用至有序搭配与两步解决问题","description":"18 个知识点、36 道小学二年级练习，每题提供默认折叠的答案、步骤和易错说明。","frontmatter":{"title":"小学二年级数学：独立习题集 · 倍的认识与倍数应用至有序搭配与两步解决问题","description":"18 个知识点、36 道小学二年级练习，每题提供默认折叠的答案、步骤和易错说明。","splitFrom":"life/math/primary/grade-2/exercises.md","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"习题与解析","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"小学二年级数学：独立习题集","summary":"18 个知识点、36 道小学二年级练习，每题提供默认折叠的答案、步骤和易错说明。","status":"active","related":[{"title":"八年级数学公式速查","link":"/life/math/junior/grade-8/formulas","kind":"公式与参考","scope":"general","audience":"general"},{"title":"八年级数学知识讲解","link":"/life/math/junior/grade-8/knowledge","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 等腰三角形与垂直平分线至加权平均数与方差","link":"/life/math/junior/grade-8/knowledge-part-02","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 平方根、立方根与实数至三角形全等与对应关系","link":"/life/math/junior/grade-8/knowledge-part-01","kind":"知识讲解","scope":"general","audience":"general"},{"title":"程序员数学 01：从编程问题选择学习路线","link":"/life/math/programmer/overview","kind":"知识讲解","scope":"general","audience":"general"}],"prev":{"text":"小学二年级数学：独立习题集 · 万以内的数与计数单位至乘除与加减混合、小括号","link":"/life/math/primary/grade-2/exercises-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"小学二年级数学：独立习题集 · 万以内的数与计数单位至乘除与加减混合、小括号","link":"/life/math/primary/grade-2/exercises-part-01"},"next":false},"headers":[],"relativePath":"life/math/primary/grade-2/exercises-part-02.md","filePath":"life/math/primary/grade-2/exercises-part-02.md"}'),p={name:"life/math/primary/grade-2/exercises-part-02.md"};function o(l,a,i,n,d,m){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="小学二年级数学-独立习题集-·-倍的认识与倍数应用至有序搭配与两步解决问题" tabindex="-1">小学二年级数学：独立习题集 · 倍的认识与倍数应用至有序搭配与两步解决问题 <a class="header-anchor" href="#小学二年级数学-独立习题集-·-倍的认识与倍数应用至有序搭配与两步解决问题" aria-label="Permalink to &quot;小学二年级数学：独立习题集 · 倍的认识与倍数应用至有序搭配与两步解决问题&quot;">​</a></h1><p><a href="/life/math/primary/grade-2/exercises">返回分篇目录</a></p><p><a href="/life/math/primary/grade-2/knowledge">知识讲解</a> · <a href="/life/math/primary/grade-2/formulas">公式速查</a> · <a href="/life/math/primary/grade-2/exercises">独立习题集</a></p><p>按六三三学段编排的通用建议学习顺序；不同地区、教材和学期安排存在差异。本版覆盖以下明确列出的知识点，不将其等同于所有教材或完整课程标准。</p><h2 id="p2-10" tabindex="-1">倍的认识与倍数应用 <a class="header-anchor" href="#p2-10" aria-label="Permalink to &quot;倍的认识与倍数应用 {#p2-10}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-10">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-10">公式规则</a></p><h3 id="q19" tabindex="-1">题 19 <a class="header-anchor" href="#q19" aria-label="Permalink to &quot;题 19 {#q19}&quot;">​</a></h3><p>小军有 5 张卡片，小兰有 20 张。小兰的卡片数是小军的几倍？</p><p>知识点：p2-10 倍的认识与倍数应用。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 4 倍。</p><p><strong>推导步骤：</strong> 以小军的 5 张为一份，20÷5＝4。</p><p><strong>易错提醒：</strong> 答案写“4 倍”，不写“4 张倍”。</p></details><h3 id="q20" tabindex="-1">题 20 <a class="header-anchor" href="#q20" aria-label="Permalink to &quot;题 20 {#q20}&quot;">​</a></h3><p>白兔有 6 只，黑兔的只数是白兔的 3 倍。两种兔一共有多少只？</p><p>知识点：p2-10 倍的认识与倍数应用。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 24 只。</p><p><strong>推导步骤：</strong> 黑兔有 6×3＝18 只，两种共 6＋18＝24 只。</p><p><strong>易错提醒：</strong> 18 是黑兔数量，还不是两种总数。</p></details><h2 id="p2-11" tabindex="-1">毫米、厘米、分米、米与千米 <a class="header-anchor" href="#p2-11" aria-label="Permalink to &quot;毫米、厘米、分米、米与千米 {#p2-11}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-11">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-11">公式规则</a></p><h3 id="q21" tabindex="-1">题 21 <a class="header-anchor" href="#q21" aria-label="Permalink to &quot;题 21 {#q21}&quot;">​</a></h3><p>3 分米 4 厘米等于多少厘米？</p><p>知识点：p2-11 毫米、厘米、分米、米与千米。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 34 厘米。</p><p><strong>推导步骤：</strong> 3 分米＝30 厘米，加上 4 厘米得到 34 厘米。</p><p><strong>易错提醒：</strong> 应把分米换成厘米后再加。</p></details><h3 id="q22" tabindex="-1">题 22 <a class="header-anchor" href="#q22" aria-label="Permalink to &quot;题 22 {#q22}&quot;">​</a></h3><p>一条跑道长 400 米，跑 2 圈后再跑 200 米，总共跑了多少米？合多少千米？</p><p>知识点：p2-11 毫米、厘米、分米、米与千米。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 1000 米，合 1 千米。</p><p><strong>推导步骤：</strong> 400×2＋200＝1000 米；1000 米＝1 千米。</p><p><strong>易错提醒：</strong> 400 米是每圈长度，2 圈要先乘 2。</p></details><h2 id="p2-12" tabindex="-1">克、千克与质量比较 <a class="header-anchor" href="#p2-12" aria-label="Permalink to &quot;克、千克与质量比较 {#p2-12}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-12">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-12">公式规则</a></p><h3 id="q23" tabindex="-1">题 23 <a class="header-anchor" href="#q23" aria-label="Permalink to &quot;题 23 {#q23}&quot;">​</a></h3><p>一袋米重 5 千克，两袋同样的米一共重多少千克？</p><p>知识点：p2-12 克、千克与质量比较。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 10 千克。</p><p><strong>推导步骤：</strong> 每袋 5 千克，共 2 袋，5×2＝10 千克。</p><p><strong>易错提醒：</strong> 份数没有质量单位，积保留千克。</p></details><h3 id="q24" tabindex="-1">题 24 <a class="header-anchor" href="#q24" aria-label="Permalink to &quot;题 24 {#q24}&quot;">​</a></h3><p>一盒点心连盒重 950 克，空盒重 150 克。点心净重多少克？比 1 千克少多少克？</p><p>知识点：p2-12 克、千克与质量比较。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 净重 800 克，比 1 千克少 200 克。</p><p><strong>推导步骤：</strong> 950−150＝800 克；1 千克＝1000 克，1000−800＝200 克。</p><p><strong>易错提醒：</strong> 不能把含盒总质量当作净质量。</p></details><h2 id="p2-13" tabindex="-1">角、顶点与直角 <a class="header-anchor" href="#p2-13" aria-label="Permalink to &quot;角、顶点与直角 {#p2-13}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-13">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-13">公式规则</a></p><h3 id="q25" tabindex="-1">题 25 <a class="header-anchor" href="#q25" aria-label="Permalink to &quot;题 25 {#q25}&quot;">​</a></h3><p>把一个直角的两条边都延长，得到的角还是直角吗？说明理由。</p><p>知识点：p2-13 角、顶点与直角。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 还是直角。</p><p><strong>推导步骤：</strong> 延长只改变画出的边长，未改变两边张开的程度，角的大小不变。</p><p><strong>易错提醒：</strong> 边更长不表示角更大。</p></details><h3 id="q26" tabindex="-1">题 26 <a class="header-anchor" href="#q26" aria-label="Permalink to &quot;题 26 {#q26}&quot;">​</a></h3><p>长方形纸片有几个直角？旋转纸片后直角的个数会改变吗？</p><p>知识点：p2-13 角、顶点与直角。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 4 个；不会改变。</p><p><strong>推导步骤：</strong> 长方形四个顶点处都是直角；旋转是整体位置变化，不改变形状。</p><p><strong>易错提醒：</strong> 斜放后不能只靠视觉认定“不直”。</p></details><h2 id="p2-14" tabindex="-1">轴对称、平移与旋转初步 <a class="header-anchor" href="#p2-14" aria-label="Permalink to &quot;轴对称、平移与旋转初步 {#p2-14}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-14">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-14">公式规则</a></p><h3 id="q27" tabindex="-1">题 27 <a class="header-anchor" href="#q27" aria-label="Permalink to &quot;题 27 {#q27}&quot;">​</a></h3><p>一扇推拉窗沿水平方向滑开，主要是平移还是旋转？窗的形状和大小会改变吗？</p><p>知识点：p2-14 轴对称、平移与旋转初步。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 平移；形状和大小不变。</p><p><strong>推导步骤：</strong> 窗整体向同一方向滑动，各部分移动相同距离，不绕固定点转动。</p><p><strong>易错提醒：</strong> 不要把所有“移动”都叫旋转。</p></details><h3 id="q28" tabindex="-1">题 28 <a class="header-anchor" href="#q28" aria-label="Permalink to &quot;题 28 {#q28}&quot;">​</a></h3><p>一张普通长方形纸，长与宽不相等，沿哪两条直线对折能完全重合？对角线可以吗？</p><p>知识点：p2-14 轴对称、平移与旋转初步。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 沿经过中心、分别平行于两组边的两条直线；对角线不可以。</p><p><strong>推导步骤：</strong> 左右对折或上下对折都能重合；沿对角线折叠，长边不能与较短边完全贴合。</p><p><strong>易错提醒：</strong> 正方形的对称轴情况不能直接套到非正方形长方形。</p></details><h2 id="p2-15" tabindex="-1">周长的初步认识 <a class="header-anchor" href="#p2-15" aria-label="Permalink to &quot;周长的初步认识 {#p2-15}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-15">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-15">公式规则</a></p><h3 id="q29" tabindex="-1">题 29 <a class="header-anchor" href="#q29" aria-label="Permalink to &quot;题 29 {#q29}&quot;">​</a></h3><p>正方形贴纸每边长 4 厘米，沿边框贴一圈彩带需要多少厘米？不考虑接头。</p><p>知识点：p2-15 周长的初步认识。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 16 厘米。</p><p><strong>推导步骤：</strong> 四条边同长，4×4＝16 厘米。</p><p><strong>易错提醒：</strong> 计算的是一周长度，不是 4＋4。</p></details><h3 id="q30" tabindex="-1">题 30 <a class="header-anchor" href="#q30" aria-label="Permalink to &quot;题 30 {#q30}&quot;">​</a></h3><p>长方形卡片长 8 厘米、宽 3 厘米，周长是多少厘米？</p><p>知识点：p2-15 周长的初步认识。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 22 厘米。</p><p><strong>推导步骤：</strong> 相邻两边和为 8＋3＝11 厘米，两组相同，11×2＝22 厘米。</p><p><strong>易错提醒：</strong> 只算长加宽得到的是半个周长。</p></details><h2 id="p2-16" tabindex="-1">时、分、钟面读数与经过时间 <a class="header-anchor" href="#p2-16" aria-label="Permalink to &quot;时、分、钟面读数与经过时间 {#p2-16}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-16">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-16">公式规则</a></p><h3 id="q31" tabindex="-1">题 31 <a class="header-anchor" href="#q31" aria-label="Permalink to &quot;题 31 {#q31}&quot;">​</a></h3><p>分针指 8，时针在 2 与 3 之间，已经经过 2，钟面表示几时几分？</p><p>知识点：p2-16 时、分、钟面读数与经过时间。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 2 时 40 分。</p><p><strong>推导步骤：</strong> 8 个大格是 8×5＝40 分，时针已经过 2，所以是 2:40。</p><p><strong>易错提醒：</strong> 时针接近 3 不表示已经到了 3 时。</p></details><h3 id="q32" tabindex="-1">题 32 <a class="header-anchor" href="#q32" aria-label="Permalink to &quot;题 32 {#q32}&quot;">​</a></h3><p>下午 3:25 开始阅读，读了 50 分钟，几点结束？</p><p>知识点：p2-16 时、分、钟面读数与经过时间。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 下午 4:15。</p><p><strong>推导步骤：</strong> 先读 35 分钟到 4:00，还剩 50−35＝15 分钟，故 4:15 结束。</p><p><strong>易错提醒：</strong> 3:75 不是规范时间表示，75 分应进 1 时余 15 分。</p></details><h2 id="p2-17" tabindex="-1">调查记录、统计表与图形计数 <a class="header-anchor" href="#p2-17" aria-label="Permalink to &quot;调查记录、统计表与图形计数 {#p2-17}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-17">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-17">公式规则</a></p><h3 id="q33" tabindex="-1">题 33 <a class="header-anchor" href="#q33" aria-label="Permalink to &quot;题 33 {#q33}&quot;">​</a></h3><p>调查 15 名同学，每人只选一种运动：跳绳 6 人、跑步 5 人，其余选游泳。选游泳的有几人？</p><p>知识点：p2-17 调查记录、统计表与图形计数。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 4 人。</p><p><strong>推导步骤：</strong> 已知两类共 6＋5＝11 人，15−11＝4 人。</p><p><strong>易错提醒：</strong> 只选一种保证没有重复计数；否则不能这样相减。</p></details><h3 id="q34" tabindex="-1">题 34 <a class="header-anchor" href="#q34" aria-label="Permalink to &quot;题 34 {#q34}&quot;">​</a></h3><p>读书图中每颗星代表 3 本书，甲有 4 颗星，乙有 2 颗星。甲比乙多读多少本？</p><p>知识点：p2-17 调查记录、统计表与图形计数。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 6 本。</p><p><strong>推导步骤：</strong> 甲读 4×3＝12 本，乙读 2×3＝6 本，相差 6 本；也可算 (4−2)×3。</p><p><strong>易错提醒：</strong> 两颗星的差不是两本书。</p></details><h2 id="p2-18" tabindex="-1">有序搭配与两步解决问题 <a class="header-anchor" href="#p2-18" aria-label="Permalink to &quot;有序搭配与两步解决问题 {#p2-18}&quot;">​</a></h2><p><a href="/life/math/primary/grade-2/knowledge#p2-18">复习讲解</a> · <a href="/life/math/primary/grade-2/formulas#p2-18">公式规则</a></p><h3 id="q35" tabindex="-1">题 35 <a class="header-anchor" href="#q35" aria-label="Permalink to &quot;题 35 {#q35}&quot;">​</a></h3><p>有红、蓝 2 顶帽子和白、黑、黄 3 条围巾，任选一顶帽子与一条围巾，共有多少种搭配？</p><p>知识点：p2-18 有序搭配与两步解决问题。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 6 种。</p><p><strong>推导步骤：</strong> 红帽可搭白、黑、黄 3 种围巾，蓝帽也有 3 种，共 3＋3＝6 种。</p><p><strong>易错提醒：</strong> 颜色组合相同才算重复，不能只数颜色种类。</p></details><h3 id="q36" tabindex="-1">题 36 <a class="header-anchor" href="#q36" aria-label="Permalink to &quot;题 36 {#q36}&quot;">​</a></h3><p>每本本子 7 元，买 4 本，付 50 元，应找回多少元？</p><p>知识点：p2-18 有序搭配与两步解决问题。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 22 元。</p><p><strong>推导步骤：</strong> 先算总价 7×4＝28 元，再算找零 50−28＝22 元。</p><p><strong>易错提醒：</strong> 先明确 7 元是一本的价格，不能只减去 7。</p></details>',94)])])}const c=r(p,[["render",o]]);export{g as __pageData,c as default};
